function syncPath(filePath) {
  const fd = openSync(filePath, "r");
  let failure;
  try {
    fsyncSync(fd);
  } catch (error) {
    failure = error;
  }
  try {
    closeSync(fd);
  } catch (error) {
    failure ??= error;
  }
  if (failure) throw failure;
}

function syncDirectoryChain(dirPath) {
  const absoluteDir = path.resolve(dirPath);
  const root = path.parse(absoluteDir).root;
  let current = absoluteDir;
  for (;;) {
    syncPath(current);
    if (current === root) break;
    current = path.dirname(current);
  }
}

